/**
 * Java Mapper 生成器（MyBatis-Plus DAO）
 * IR → BaseMapper 接口
 *
 * 输出：generated/mapper/XxxMapper.java
 * 主键类型跟随实体的 idType。
 */
import { writeFileSync, mkdirSync, existsSync, rmSync } from 'fs'
import { join } from 'path'

const HEADER = [
  '// AUTO-GENERATED by polyforge. DO NOT EDIT.',
  '// 源：模型定义的 entities 段',
  '',
]

const PKG = 'com.we.engine.server.generated.mapper'
const PKG_ENTITY = 'com.we.engine.server.generated.entity'

/** 主键 Java 类型（C18 保证每个实体恰有一个 id 字段） */
function idJavaType(entity) {
  for (const fd of Object.values(entity.fields)) {
    if (fd.type === 'id' && !fd.ref) {
      return (fd.idType === 'long' || !fd.idType) ? 'Long' : 'String'
    }
  }
  throw new Error('实体缺少主键字段: ' + entity.name + '（C18 应已拦截）')
}

/** 找出 unique 的 string 字段，生成按唯一键查询的 default 方法 */
function uniqueFinders(entity) {
  const out = []
  for (const [fn, fd] of Object.entries(entity.fields || {})) {
    if (fd.unique && fd.type === 'string') {
      const cap = fn.charAt(0).toUpperCase() + fn.slice(1)
      out.push({ method: 'findBy' + cap, field: fn })
    }
  }
  return out
}

/** 标量字段 → 查询参数 Java 类型 */
const PRIM_PARAM = {
  string: 'String', text: 'String',
  long: 'Long', int: 'Integer',
  number: 'BigDecimal', decimal: 'BigDecimal',
  boolean: 'Boolean',
}

function scalarParamType(fd) {
  if (!fd || !fd.type) return null
  if (fd.type === 'id') return (fd.idType === 'string' || fd.idType === 'uuid') ? 'String' : 'Long'
  return PRIM_PARAM[fd.type] || null
}

/** 找出 index 且非 unique 的标量字段，生成按外键/索引查询的 default 方法 */
function indexFinders(entity) {
  const out = []
  for (const [fn, fd] of Object.entries(entity.fields || {})) {
    if (!fd.index || fd.unique) continue
    const t = scalarParamType(fd)
    if (!t) continue
    const cap = fn.charAt(0).toUpperCase() + fn.slice(1)
    out.push({ method: 'findBy' + cap, field: fn, type: t })
  }
  return out
}

function renderMapper(name, entity) {
  const idType = idJavaType(entity)
  const finders = uniqueFinders(entity)
  const idxFinders = indexFinders(entity)

  const lines = [...HEADER]
  lines.push('package ' + PKG + ';')
  lines.push('')
  lines.push('import ' + PKG_ENTITY + '.' + name + ';')
  lines.push('import com.baomidou.mybatisplus.core.mapper.BaseMapper;')
  lines.push('import com.baomidou.mybatisplus.core.conditions.query.LambdaQueryWrapper;')
  lines.push('import org.apache.ibatis.annotations.Mapper;')
  if (idxFinders.length) lines.push('import java.util.List;')
  lines.push('import java.util.Optional;')
  lines.push('')
  lines.push('@Mapper')
  lines.push('public interface ' + name + 'Mapper extends BaseMapper<' + name + '> {')
  for (const f of finders) {
    lines.push('')
    lines.push('    default Optional<' + name + '> ' + f.method + '(String ' + f.field + ') {')
    lines.push('        return Optional.ofNullable(selectOne(')
    lines.push('            new LambdaQueryWrapper<' + name + '>().eq(' + name + '::get' + f.method.slice(6) + ', ' + f.field + ')));')
    lines.push('    }')
  }
  for (const f of idxFinders) {
    lines.push('')
    lines.push('    default List<' + name + '> ' + f.method + '(' + f.type + ' ' + f.field + ') {')
    lines.push('        return selectList(')
    lines.push('            new LambdaQueryWrapper<' + name + '>().eq(' + name + '::get' + f.method.slice(6) + ', ' + f.field + '));')
    lines.push('    }')
  }
  lines.push('}')
  return lines.join('\n') + '\n'
}

export function generateJavaRepository(ir, outRoot) {
  const dir = join(outRoot, 'mapper')
  // 清理旧产物：mapper 目录可能残留旧版视图映射器；repository 目录是 JPA 时代残留（已迁 MyBatis-Plus）
  if (existsSync(dir)) rmSync(dir, { recursive: true, force: true })
  mkdirSync(dir, { recursive: true })
  const legacyRepoDir = join(outRoot, 'repository')
  if (existsSync(legacyRepoDir)) rmSync(legacyRepoDir, { recursive: true, force: true })

  let count = 0
  for (const [name, entity] of ir.entities) {
    writeFileSync(join(dir, name + 'Mapper.java'), renderMapper(name, entity), 'utf-8')
    count++
  }
  console.log('  [java/mapper] ' + count + ' 个 Mapper → ' + dir)
}
